mapper.sql:
where m.shop_code = #{query.shopCode}


  and m.doccode like concat('%', #{query.docCode}, '%')



  and m.createuser = #{query.ownerScope}


  and m.doctype = #{query.docType}


  and m.doctype in

      #{type}



  and m.confirmstate = #{query.confirmState}


  and m.partnercode = #{query.partnerCode}


  and m.sourcedoccode = #{query.sourceDocCode}



  and m.docdate >= #{query.docDateBegin}


  and m.docdate <= #{query.docDateEnd}

mapper.select:
select dm.*, cu.nick_name as create_user_name,
       au.nick_name as confirm_user_name
  from (

    ( select ,
             '${suffix}' as table_suffix
        from sdsorder.u_f_docmain_${suffix} m
       )

  ) dm
  left join sys_user cu on cu.user_name = dm.createuser
  left join sys_user au on au.user_name = dm.confirmuser

mapper.delete:
delete from sdsorder.u_f_docmain_${tableSuffix}
 where shop_code = #{shopCode}
   and doccode = #{docCode}
   and confirmstate in ('待审核', '已驳回')

mapper.update:
update sdsorder.u_f_docmain_${tableSuffix}
   set confirmstate = #{confirmState},
       confirmuser = #{confirmUser},
       confirmtime = sysdate()
 where shop_code = #{shopCode}
   and doccode = #{docCode}
   and confirmstate = '待审核'

update sdsorder.u_f_docmain_${tableSuffix}
   set totalamount = #{totalAmount}
 where shop_code = #{shopCode}
   and doccode = #{docCode}

update sdsorder.u_f_docmain_${tableSuffix}
   set goodssummary = #{goodsSummary}
 where shop_code = #{shopCode}
   and doccode = #{docCode}

update sdsorder.u_f_docmain_${tableSuffix}
   set totalqty = #{totalQty},
       totalamount = #{totalAmount}
 where shop_code = #{shopCode}
   and doccode = #{docCode}
